<script lang="ts">
  import { parseData } from '$lib/content.js';
  let { data, form }: { data: import('./$types').PageData; form: { saved?: boolean; uploaded?: boolean; error?: string } | null } = $props();
  let view: any = $derived(data as any);
  let section = $state('');
  let selected: any = $derived(section ? view.rows.find((row: any) => row.key === section) : null);
  let sectionData: Record<string, string> = $derived(selected ? parseData(selected.data) as Record<string, string> : {});
</script>
