{:else if view.module === 'pengguna'}<form method="POST" action="?/createUser" class="mt-8 grid max-w-3xl gap-5 border border-stone bg-white p-6"><h2 class="text-xl font-bold">Tambah pengguna admin</h2><div class="grid gap-5 sm:grid-cols-2"><label class="grid gap-2 text-sm font-bold">Nama<input class="min-h-11 border border-stone px-3 font-normal" name="name" required /></label><label class="grid gap-2 text-sm font-bold">Email<input class="min-h-11 border border-stone px-3 font-normal" type="email" name="email" required /></label></div><div class="grid gap-5 sm:grid-cols-2"><label class="grid gap-2 text-sm font-bold">Password sementara<input class="min-h-11 border border-stone px-3 font-normal" type="password" name="password" minlength="12" required /></label><label class="grid gap-2 text-sm font-bold">Role<select class="min-h-11 border border-stone px-3 font-normal" name="role"><option>EDITOR</option><option>SUPER_ADMIN</option></select></label></div><button class="button-primary w-fit">Buat pengguna</button></form><div class="mt-8 overflow-x-auto border border-stone bg-white"><table class="w-full min-w-150 text-left text-sm"><thead class="border-b border-stone bg-mist"><tr><th class="p-4">Nama</th><th class="p-4">Email</th><th class="p-4">Role</th><th class="p-4">Status</th><th class="p-4">Login terakhir</th></tr></thead><tbody>{#each view.rows as row}<tr class="border-b border-stone"><td class="p-4 font-bold">{row.name}</td><td class="p-4">{row.email}</td><td class="p-4">{row.role}</td><td class="p-4">{row.status}</td><td class="p-4">{row.last_login_at || 'Belum pernah'}</td></tr>{/each}</tbody></table></div>
{:else}<div class="mt-8 overflow-x-auto border border-stone bg-white"><table class="w-full min-w-150 text-left text-sm"><thead class="border-b border-stone bg-mist"><tr>{#if view.rows[0]}{#each Object.keys(view.rows[0]) as key}<th class="p-4 capitalize">{key.replaceAll('_',' ')}</th>{/each}{/if}</tr></thead><tbody>{#each view.rows as row}<tr class="border-b border-stone">{#each Object.values(row) as value}<td class="p-4 text-forest">{String(value ?? '—')}</td>{/each}</tr>{/each}</tbody></table></div>{/if}</section>
